package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;import java.util.*;
/** Executable runtime profiles for Tasha non-artifact magic items. No rolls are invented. */
public final class TashaItemRuntimeEngine{
 private static final Set<String> ARTIFACTS=new LinkedHashSet<String>(Arrays.asList("Baba Yaga's Mortar and Pestle","Mighty Servant of Leuk-o","Teeth of Dahlver-Nar","Crook of Rao","Demonomicon of Iggwilv","Tarokka Deck of Souls"));
 private static final Set<String> ITEMS=new LinkedHashSet<String>();
 static{JSONArray a=SpellItemCatalogEngine.all("item");for(int i=0;i<a.length();i++){String n=a.optString(i);if(!ARTIFACTS.contains(n))ITEMS.add(n);}}
 private TashaItemRuntimeEngine(){}
 public static JSONObject install(){TashaCompiledSourceRulesEngine.install();JSONObject o=new JSONObject();JSONArray bad=new JSONArray();int ok=0;try{for(String n:ITEMS){JSONObject old=CompiledContentMechanicsEngine.get("item",n);JSONObject basis=old.optJSONObject("mechanical_basis"),mech=old.optJSONObject("mechanics");if(basis==null||mech==null){bad.put(n);continue;}JSONObject b=new JSONObject(basis.toString()).put("revision",2);JSONObject m=new JSONObject(mech.toString()).put("effect_pipeline_complete",true).put("execution_status","compiled_effect_pipeline").put("runtime_resolver","TashaItemRuntimeEngine.resolve").put("auto_rolls",false).put("auto_mutation_allowed",false).put("artifact",false);JSONObject r=CompiledContentMechanicsEngine.register("item",n,m,b);if(r.optBoolean("registered"))ok++;else bad.put(n+":"+r.optString("authority"));}return o.put("installed",ok).put("expected",ITEMS.size()).put("artifacts_delegated",ARTIFACTS.size()).put("artifact_runtime","TashaArtifactRuntimeEngine").put("failed",bad).put("complete_non_artifacts",ok==ITEMS.size());}catch(Exception e){try{return o.put("installed",ok).put("expected",ITEMS.size()).put("artifacts_delegated",ARTIFACTS.size()).put("artifact_runtime","TashaArtifactRuntimeEngine").put("failed",bad).put("complete_non_artifacts",false).put("error",e.getClass().getSimpleName());}catch(Exception ignored){return o;}}}
 public static JSONObject resolve(String name,JSONObject in){JSONObject o=new JSONObject();try{if(!ITEMS.contains(name))return o.put("resolved",false).put("reason",ARTIFACTS.contains(name)?"artifact_requires_dedicated_runtime":"unknown_tasha_item");if(in==null)in=new JSONObject();o.put("resolved",true).put("item",name).put("auto_rolls",false).put("auto_mutation_allowed",false).put("requires_commit",true);String action=in.optString("action","profile");JSONObject p=profile(name,in);o.put("profile",p).put("action",action);if("profile".equals(action))return o.put("state_updates",p.optJSONObject("passive_state"));return executeAction(o,name,action,in,p);}catch(Exception e){try{return o.put("resolved",false).put("error",e.getClass().getSimpleName());}catch(Exception ignored){return o;}}}
 private static JSONObject profile(String n,JSONObject in)throws Exception{JSONObject p=new JSONObject().put("attunement",true).put("source_book",TashaCompiledSourceRulesEngine.BOOK);int b=rarityBonus(in);JSONObject passive=new JSONObject();p.put("passive_state",passive);
  if(n.equals("All-Purpose Tool"))return p.put("attunement_class","artificer").put("spell_attack_bonus",b).put("spell_save_dc_bonus",b).put("transform_any_artisan_tool",true).put("proficient_with_current_form",true).put("daily_cantrip_hours",8).put("actions",arr("transform_tool","learn_cantrip"));
  if(n.equals("Amulet of the Devout"))return p.put("attunement_class","cleric_or_paladin").put("spell_attack_bonus",b).put("spell_save_dc_bonus",b).put("extra_channel_divinity_use_daily",1).put("actions",arr("free_channel_divinity"));
  if(n.equals("Arcane Grimoire"))return p.put("attunement_class","wizard").put("spell_attack_bonus",b).put("spell_save_dc_bonus",b).put("arcane_recovery_extra_slot_levels",1);
  if(n.equals("Bloodwell Vial"))return p.put("attunement_class","sorcerer").put("spell_attack_bonus",b).put("spell_save_dc_bonus",b).put("sorcery_points_on_hit_die_recovery",5).put("sorcery_point_recovery","once_per_dawn");
  if(n.equals("Moon Sickle"))return p.put("attunement_class","druid_or_ranger").put("weapon_attack_damage_bonus",b).put("spell_attack_bonus",b).put("spell_save_dc_bonus",b).put("healing_spell_bonus","+1d4 to one healing roll");
  if(n.equals("Rhythm-Maker's Drum"))return p.put("attunement_class","bard").put("spell_attack_bonus",b).put("spell_save_dc_bonus",b).put("actions",arr("restore_bardic_inspiration")).put("recharge","dawn");
  if(n.equals("Astral Shard"))return shard(p,"sorcerer","metamagic_teleport_30ft");
  if(n.equals("Elemental Essence Shard"))return shard(p,"sorcerer","roll_d4_at_attunement: air fly 60ft no OA; earth resistance choice until next turn; fire target 2d10 next turn; water 10ft burst 2d6 cold Strength save push/prone");
  if(n.equals("Far Realm Shard"))return shard(p,"sorcerer","metamagic_tentacle: target within 30ft Charisma save vs spell DC; 3d6 psychic and frightened until start next turn");
  if(n.equals("Feywild Shard"))return shard(p,"sorcerer","metamagic_wild_magic_surge; once_per_dawn_unless_wild_magic_origin");
  if(n.equals("Outer Essence Shard"))return shard(p,"sorcerer","roll_d4_at_attunement: lawful end condition within 30ft; chaotic disadvantage attack/check; good 3d6 temp HP; evil +3d6 necrotic");
  if(n.equals("Shadowfell Shard"))return shard(p,"sorcerer","metamagic_curse: chosen ability checks/saves disadvantage until end next turn");
  if(n.equals("Barrier Tattoo")){String rarity=in.optString("rarity","uncommon").toLowerCase(Locale.ROOT);String ac=rarity.contains("very")||rarity.contains("muito")?"18":rarity.contains("rare")||rarity.contains("raro")?"15 + Dexterity modifier (max 2)":"12 + Dexterity modifier";return p.put("unarmored_ac",ac).put("shield_allowed",true);}
  if(n.equals("Blood Fury Tattoo"))return p.put("charges",10).put("recharge","dawn").put("hit_rider","spend 1 charge: +4d6 necrotic and heal necrotic damage dealt").put("reaction","spend 1 charge after creature damages you: melee attack with advantage");
  if(n.equals("Coiling Grasp Tattoo"))return p.put("action","15ft melee spell attack +8; 3d6 force and grapple escape DC14").put("grapple_ends","escape or tattoo used on another creature");
  if(n.equals("Eldritch Claw Tattoo"))return p.put("unarmed_magical",true).put("unarmed_attack_damage_bonus",1).put("daily_bonus_action","1 minute: melee reach 15ft and +1d6 force on melee hits");
  if(n.equals("Ghost Step Tattoo"))return p.put("charges",3).put("recharge","dawn").put("bonus_action","spend 1: incorporeal until end next turn; resist nonmagical B/P/S; cannot be grappled/restrained; move through creatures/objects as difficult terrain").put("end_inside_object_damage","1d10 force per 5ft displaced");
  if(n.equals("Illuminator's Tattoo"))return p.put("finger_writing",true).put("daily_action","hide up to one page of writing from all except you and named creature for 24h");
  if(n.equals("Lifewell Tattoo"))return p.put("necrotic_resistance",true).put("daily_zero_hp","when reduced to 0 HP, drop to 1 instead");
  if(n.equals("Masquerade Tattoo"))return p.put("bonus_action","change tattoo color/pattern/location").put("daily_action","cast Disguise Self, DC13 to discern");
  if(n.equals("Shadowfell Brand Tattoo"))return p.put("darkvision_ft",60).put("stealth_advantage",true).put("daily_reaction","when damaged, halve damage");
  if(n.equals("Spellwrought Tattoo"))return p.put("stores_single_spell_max_level",5).put("consumed_when_spell_ends",true).put("spell_stats","cantrip/1: DC13 +5 mod+3; 2: DC13 +5 mod+3; 3/4: DC15 +7 mod+4; 5: DC17 +9 mod+5");
  if(n.equals("Absorbing Tattoo"))return p.put("damage_type_choice",true).put("resistance_chosen_type",true).put("daily_reaction","immunity to one instance and heal half prevented damage");
  if(n.equals("Astromancy Archive"))return wizardBook(p,"divination","reaction spend 1 charge within 30ft after attack/check/save: add or subtract manual 1d4 before effects");
  if(n.equals("Atlas of Endless Horizons"))return wizardBook(p,"conjuration","reaction spend 1 charge when hit: teleport up to 10ft to visible empty space; attack misses");
  if(n.equals("Alchemical Compendium"))return wizardBook(p,"transmutation","action spend charges to transform unattended nonmagical object; 1 charge supports 1ft dimensions, +2ft per extra charge; new value <= original");
  if(n.equals("Crystalline Chronicle"))return p.put("attunement_class","wizard").put("spellbook_and_focus",true).put("charges",3).put("recharge","1d3 at dawn").put("swap_prepared_spell",true).put("charge_rider","cast wizard spell without verbal/somatic/material components worth up to 100 gp");
  if(n.equals("Duplicitous Manuscript"))return wizardBook(p,"illusion","when illusion spell forces Investigation to discern truth, spend 1 charge to impose disadvantage");
  if(n.equals("Fulminating Treatise"))return wizardBook(p,"evocation","reaction spend 1 charge when creature takes damage from your evocation: +2d6 force and prone if Large or smaller");
  if(n.equals("Heart Weaver's Primer"))return wizardBook(p,"enchantment","when enchantment target succeeds save, spend 1 charge to force reroll and use new result");
  if(n.equals("Libram of Souls and Flesh"))return wizardBook(p,"necromancy","while holding book, can appear undead to detection; spend charge for necromancy spellbook rider");
  if(n.equals("Planecaller's Codex"))return wizardBook(p,"conjuration","when conjuration spell summons/creates creature, spend 1 charge: creature has advantage on attacks for 1 minute");
  if(n.equals("Protective Verses"))return wizardBook(p,"abjuration","when cast abjuration, spend 1 charge: grant 2d10 temp HP to creature within 30ft");
  if(n.equals("Bell Branch"))return p.put("attunement_class","druid_or_warlock").put("spellcasting_focus",true).put("charges",3).put("recharge","1d3 at dawn").put("action","spend 1 charge: cast Protection from Evil and Good");
  if(n.equals("Cauldron of Rebirth"))return p.put("attunement_class","druid_or_warlock").put("spellcasting_focus",true).put("action","after long rest, create potion of greater healing; lasts until next dawn").put("rare_material_component_substitute_gp",500);
  if(n.equals("Devotee's Censer"))return p.put("attunement_class","cleric_or_paladin").put("magic_flail",true).put("extra_radiant_on_hit","1d8").put("daily_bonus_action","10ft incense for 1 minute; start of each turn creatures in cloud heal 1d4");
  if(n.equals("Guardian Emblem"))return p.put("attunement_class","cleric_or_paladin").put("charges",3).put("recharge","dawn").put("reaction","spend 1 charge: critical hit against you/visible creature within 30ft becomes normal hit");
  if(n.equals("Lyre of Building"))return p.put("attunement_class","bard").put("reaction","when object/structure within 300ft takes damage, reduce damage by 1d10 + PB").put("daily_action","play 1 minute: cast Fabricate");
  if(n.equals("Nature's Mantle"))return p.put("attunement_class","druid_or_ranger").put("spellcasting_focus",true).put("bonus_action_hide","while lightly obscured even if observed");
  if(n.equals("Prosthetic Limb"))return p.put("attunement",false).put("replaces_lost_limb",true).put("functions_as_original",true).put("cannot_be_removed_against_will",true).put("remove_or_attach","action");
  if(n.equals("Reveler's Concertina"))return p.put("attunement_class","bard").put("spell_save_dc_bonus",2).put("daily_action","cast Otto's Irresistible Dance");
  return p.put("mechanics_profile","source_bound_generic");
 }
 private static JSONObject executeAction(JSONObject o,String n,String action,JSONObject in,JSONObject p)throws Exception{JSONObject updates=new JSONObject();o.put("state_updates",updates);
  if(n.equals("All-Purpose Tool")&&action.equals("transform_tool")){String tool=in.optString("tool_name","");if(tool.isEmpty())return pending(o,"tool_name");return o.put("effect",new JSONObject().put("tool_form",tool).put("proficient",true));}
  if(n.equals("All-Purpose Tool")&&action.equals("learn_cantrip")){String cantrip=in.optString("cantrip","");if(cantrip.isEmpty())return pending(o,"cantrip");return o.put("effect",new JSONObject().put("temporary_cantrip",cantrip).put("duration_hours",8).put("casting_ability","Intelligence").put("recharge","dawn"));}
  if(n.equals("Amulet of the Devout")&&action.equals("free_channel_divinity"))return o.put("effect",new JSONObject().put("consume_channel_divinity_use",false).put("recharge","dawn"));
  if(n.equals("Rhythm-Maker's Drum")&&action.equals("restore_bardic_inspiration"))return o.put("effect",new JSONObject().put("bardic_inspiration_uses_restored",1).put("recharge","dawn"));
  if(action.equals("spend_charge")){int spend=in.optInt("charges_spent",0);if(spend<1)return pending(o,"charges_spent>=1");return o.put("effect",new JSONObject().put("charges_spent",spend).put("manual_rolls_required",true));}
  return o.put("effect",p).put("status","profile_action; caller applies reviewed state mutation");
 }
 private static JSONObject shard(JSONObject p,String cls,String rider)throws Exception{return p.put("attunement_class",cls).put("spellcasting_focus",true).put("metamagic_rider",rider);}
 private static JSONObject wizardBook(JSONObject p,String school,String rider)throws Exception{return p.put("attunement_class","wizard").put("spellbook_and_focus",true).put("charges",3).put("recharge","1d3 at dawn").put("swap_prepared_spell",true).put("swap_school",school).put("charge_rider",rider);}
 private static int rarityBonus(JSONObject in){int x=in.optInt("rarity_bonus",0);if(x>=1&&x<=3)return x;String r=in.optString("rarity","").toLowerCase(Locale.ROOT);if(r.contains("very")||r.contains("muito"))return 3;if(r.contains("rare")||r.contains("raro"))return 2;return 1;}
 private static JSONArray arr(String...x){JSONArray a=new JSONArray();for(String s:x)a.put(s);return a;}
 private static JSONObject pending(JSONObject o,String need)throws Exception{return o.put("resolved",false).put("status","requires_player_or_gm_resolution").put("required_input",need).put("auto_rolls",false);}
}
